{
  "findings": [
    {
      "check_id": "CKV_AZURE_1",
      "title": "Ensure HTTPS is enforced for storage account",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "HIGH",
      "explanation": "The attribute 'enable_https_traffic_only' is explicitly set to false, allowing unencrypted HTTP traffic to the storage account. This exposes data in transit to interception and man-in-the-middle attacks."
    },
    {
      "check_id": "CKV2_AZURE_47",
      "title": "Ensure storage account is configured without blob anonymous access",
      "resource": "azurerm_storage_account.notification_storage",
      "severity": "MEDIUM",
      "explanation": "The resource does not explicitly disable public network access or configure the blob container to prevent anonymous access. By default, if not restricted, this can lead to unintended data exposure."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"notification_storage\" {\n  name                     = \"smartgridscada${random_string.suffix.result}\"\n  resource_group_name      = azurerm_resource_group.smart_grid_rg.name\n  location                 = azurerm_resource_group.smart_grid_rg.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"LRS\"\n  enable_https_traffic_only = true\n  min_tls_version          = \"TLS1_2\"\n  public_network_access_enabled = false\n}",
  "fix_summary": "Changed 'enable_https_traffic_only' from false to true to enforce encrypted transport. Added 'min_tls_version' = \"TLS1_2\" to ensure modern encryption standards. Set 'public_network_access_enabled' to false to restrict access to private endpoints only, mitigating risks of anonymous or public exposure."
}
